const body = $input.first().json.body || $input.first().json;
const customerId = body.customer_id || body.customerId;
if (!customerId) {
  return [{ json: { ok: false, error: 'missing_customer_id', message: 'get_customer requires { customer_id }.', _status: 400 } }];
}
const customer = customers.find(c => c.customer_id === customerId);
if (!customer) {
  return [{ json: { ok: false, error: 'customer_not_found', message: `No customer with id ${customerId}`, customer_id: customerId, _status: 404 } }];
}
return [{ json: { ok: true, customer, _status: 200 } }];
